arguments.command:
cd /workspace && python - <<'EOF'
big = 10**400
neg = -10**400
for expr in ['f"{big:,}"', 'f"{neg:,}"', 'format(big, ",.2f")', 'format(big, ",d")']:
    try:
        print(expr, "=>", eval(expr))
    except Exception as e:
        print(expr, "ERR", type(e).__name__, e)
try:
    print(float(big))
except Exception as e:
    print("float(big) ->", type(e).__name__, e)
from decimal import Decimal
print("Decimal(big):", str(Decimal(big))[:20])
print("format Decimal big:", format(Decimal(big), ','))
try:
    print(format(Decimal(big), ',.2f'))
except Exception as e:
    print("dec fmt err", type(e).__name__, e)
print(format(10123.001, ',.2f'))
print(round(10123.001))
print(int(10123.001))
EOF

